<script setup lang="ts">
import {onMounted,ref} from 'vue';import {api} from '../api';import PageShell from '../components/PageShell.vue';
interface Status {version:string;disk:{total:number;free:number;usage:number};databaseBytes:number;backup:{schedule:{frequency:string};running:boolean;latest:{ok:boolean;at:string;message?:string}|null;lastSuccessAt:string|null;lastFailureAt:string|null;nextRun:string|null;backups:number};jobs:Record<string,number>;failedLogins:number;activeGrants:number;apiKeys:number;alerts:{key:string;severity:string;message:string;active:number;changedAt:string}[]}
const status=ref<Status>(),error=ref('');async function load(){try{status.value=await api('/system');}catch(e){error.value=(e as Error).message;}}onMounted(load);
const size=(n:number)=>`${(n/1024/1024).toFixed(1)} MB`;
const jobLabels:Record<string,string>={backup:'自动备份',notifications:'站内提醒',apprise:'外部通知',push:'浏览器推送',system:'系统检查'};
const severityLabels:Record<string,string>={warning:'提醒',critical:'告警'};
</script>
<template><PageShell :entry="false"><section class="panel"><div class="row"><h2>系统状态</h2><button class="quiet" @click="load">刷新</button></div><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="status"><dl class="status-grid"><div><dt>版本</dt><dd>{{status.version}}</dd></div><div><dt>磁盘使用</dt><dd>{{Math.round(status.disk.usage*100)}}% · 剩余 {{size(status.disk.free)}}</dd></div><div><dt>数据库</dt><dd>{{size(status.databaseBytes)}}</dd></div><div><dt>备份任务</dt><dd>{{status.backup.running?'正在运行':'空闲'}}</dd></div><div><dt>最近成功 / 失败</dt><dd>{{status.backup.lastSuccessAt?new Date(status.backup.lastSuccessAt).toLocaleString('zh-CN'):'无'}} / {{status.backup.lastFailureAt?new Date(status.backup.lastFailureAt).toLocaleString('zh-CN'):'无'}}</dd></div><div><dt>下次备份</dt><dd>{{status.backup.nextRun?new Date(status.backup.nextRun).toLocaleString('zh-CN'):'未计划'}}</dd></div><div><dt>一小时失败登录</dt><dd>{{status.failedLogins}}</dd></div><div><dt>有效 MCP 授权 / API Key</dt><dd>{{status.activeGrants}} / {{status.apiKeys}}</dd></div></dl><h3>后台任务</h3><p v-for="(heartbeat,name) in status.jobs" :key="name">{{jobLabels[name]||name}} · 最近运行 {{new Date(heartbeat).toLocaleString('zh-CN')}}</p><h3>告警</h3><p v-if="!status.alerts.some(v=>v.active)" class="muted">当前没有活动告警。</p><p v-for="alert in status.alerts.filter(v=>v.active)" :key="alert.key" class="error">{{severityLabels[alert.severity]||alert.severity}}：{{alert.message}}</p><RouterLink to="/backups">管理备份 →</RouterLink></template></section></PageShell></template>
<style scoped>.status-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:1rem}.status-grid div{padding:1rem;border:1px solid var(--border);border-radius:var(--radius,12px)}dt{color:var(--muted)}dd{margin:.4rem 0 0;font-weight:600}</style>
